// D1 v1.09 item tables, generated by scripts/extract_d1.py from devilution Source/itemdat.cpp (AllItemsList, PL_Prefix, PL_Suffix).
import raw from './gen/itemdat.json';

export interface BaseItem {
  iRnd: string; iClass: string; iLoc: string; iCurs: string; itype: string; iItemId: string;
  iName: string; iSName: string | null; iMinMLvl: number; iDurability: number;
  iMinDam: number; iMaxDam: number; iMinAC: number; iMaxAC: number;
  iMinStr: number; iMinMag: number; iMinDex: number; iFlags: string; iMiscId: string;
  iSpell: string; iUsable: boolean; iValue: number; iMaxValue: number;
}
export interface Affix {
  name: string; power: string; p1: number; p2: number; minlvl: number; itype: string[];
  goe: string; double: boolean; ok: boolean; minval: number; maxval: number; mult: number;
}
export const BASE: BaseItem[] = (raw as { items: BaseItem[] }).items;
export const PREFIXES: Affix[] = (raw as { prefixes: Affix[] }).prefixes;
export const SUFFIXES: Affix[] = (raw as { suffixes: Affix[] }).suffixes;

export function idxOf(name: string): number {
  const i = BASE.findIndex((b) => b.iName === name);
  if (i < 0) throw new Error(`no base item ${name}`);
  return i;
}
/** Named indexes (IDI_*) the game needs. */
export const IDI = {
  GOLD: 0,
  WARRIOR: idxOf('Short Sword'), WARRSHLD: idxOf('Buckler'), WARRCLUB: idxOf('Club'),
  ROGUE: idxOf('Short Bow'), SORCEROR: idxOf('Short Staff of Charged Bolt'),
  HEAL: idxOf('Potion of Healing'), FULLHEAL: idxOf('Potion of Full Healing'),
  MANA: idxOf('Potion of Mana'), FULLMANA: idxOf('Potion of Full Mana'),
  PORTAL: BASE.findIndex((b) => b.iMiscId === 'IMISC_SCROLL' && b.iSpell === 'SPL_TOWN'),
  CLEAVER: idxOf('Cleaver'),
  REJUV: BASE.findIndex((b) => b.iMiscId === 'IMISC_REJUV'),
  FULLREJUV: BASE.findIndex((b) => b.iMiscId === 'IMISC_FULLREJUV'),
};

/** Inventory cell size (w,h) from the D1 cursor art size. [TEMP] approximated per item type, not read from objcurs.cel. */
export function itemSize(b: BaseItem): [number, number] {
  switch (b.itype) {
    case 'ITYPE_SWORD': case 'ITYPE_STAFF': return [1, 3];
    case 'ITYPE_AXE': case 'ITYPE_BOW': case 'ITYPE_MACE': return b.iLoc === 'ILOC_TWOHAND' ? [2, 3] : [2, 3];
    case 'ITYPE_SHIELD': return [2, 2];
    case 'ITYPE_LARMOR': case 'ITYPE_MARMOR': case 'ITYPE_HARMOR': return [2, 3];
    case 'ITYPE_HELM': return [2, 2];
    default: return b.iMiscId === 'IMISC_BOOK' ? [2, 2] : [1, 1];
  }
}
